#include <iostream>
using namespace std;
int main() {
    int n, x, neg = 0, zero = 0, pos = 0;
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> x;
        if (x < 0) neg++;
        else if (x == 0) zero++;
        else pos++;
    }
    cout << neg << " " << zero << " " << pos << "\n";
    if (zero > 0) cout << "ZERO\n";
    else if (neg % 2 == 0) cout << "POSITIVE\n";
    else cout << "NEGATIVE\n";
    return 0;
}

