#include <iostream>
using namespace std;
int main() {
    long long x;
    cin >> x;
    int len = 0, sum = 0, rep = 0, prev = -1;
    while (x > 0) {
        int d = x % 10;
        if (d == prev) rep = 1;
        prev = d;
        sum += d;
        len++;
        x /= 10;
    }
    if (rep == 0 && len >= 6 && len <= 10 && sum >= 20) cout << "VALID\n";
    else cout << "INVALID\n";
    return 0;
}

